import{_ as a,o as t,c as i,a3 as s}from"./chunks/framework.D0yITwTA.js";const k=JSON.parse('{"title":"Command Line Interface","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cli.md","filePath":"guide/cli.md"}'),n={name:"guide/cli.md"};function o(d,e,h,r,l,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="command-line-interface" tabindex="-1">Command Line Interface <a class="header-anchor" href="#command-line-interface" aria-label="Permalink to &quot;Command Line Interface&quot;">​</a></h1><p>OWL-SDA ships as a single executable jar at <code>target/owlsda.jar</code> (see <a href="./installation">Installation</a> for how to build it). Everything the tool does is driven by one command with a handful of options - there are no subcommands and no positional arguments.</p><p>Run it with a Java 25 runtime:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/owlsda.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/project-1/config.yml</span></span></code></pre></div><h2 id="synopsis" tabindex="-1">Synopsis <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;Synopsis&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Usage: owlsda [-hV] [--web-ui] -c=&lt;configLocation&gt; [--web-ui-port=&lt;webUiPort&gt;]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>-c</code>, <code>--config=&lt;location&gt;</code></td><td><em>(none - required)</em></td><td>Location of the YAML configuration file. Accepts a plain path or an explicit <code>file:</code> / <code>classpath:</code> prefix.</td></tr><tr><td><code>--web-ui</code></td><td><code>false</code></td><td>Start the local web dashboard alongside the run.</td></tr><tr><td><code>--web-ui-port=&lt;port&gt;</code></td><td><code>8080</code></td><td>Port the dashboard listens on.</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td></td><td>Print the usage message and exit.</td></tr><tr><td><code>-V</code>, <code>--version</code></td><td></td><td>Print the version (<code>1.0-SNAPSHOT</code>) and exit.</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/owlsda.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/owlsda.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="config-is-required" tabindex="-1"><code>--config</code> Is Required <a class="header-anchor" href="#config-is-required" aria-label="Permalink to &quot;\`--config\` Is Required&quot;">​</a></h2><p>There is no default configuration file. Running the jar with no arguments is a usage error - it prints the missing-option message plus the usage block and exits with code <code>2</code> without contacting any model:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/owlsda.jar</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Missing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> required</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> option:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;--config=&lt;configLocation&gt;&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Usage:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> owlsda</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-hV] [--web-ui] -c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">configLocation</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> [--web-ui-port</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;webUiPort&gt;]</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span></code></pre></div><p>This is deliberate. Earlier versions defaulted to <code>examples/project-1/config.yml</code>, so a bare <code>java -jar target/owlsda.jar</code> silently started a real run: it overwrote that example&#39;s outputs and spent real LLM API tokens. Always name the configuration you mean to run.</p><h2 id="how-the-configuration-location-is-resolved" tabindex="-1">How the Configuration Location Is Resolved <a class="header-anchor" href="#how-the-configuration-location-is-resolved" aria-label="Permalink to &quot;How the Configuration Location Is Resolved&quot;">​</a></h2><p>The value of <code>--config</code> is resolved in one of three ways, depending on its prefix:</p><table tabindex="0"><thead><tr><th>Prefix</th><th>Example</th><th>Behaviour</th></tr></thead><tbody><tr><td><em>(none)</em></td><td><code>examples/project-1/config.yml</code></td><td>Tries the classpath first; if no such resource exists, falls back to the filesystem path.</td></tr><tr><td><code>file:</code></td><td><code>file:examples/project-1/config.yml</code></td><td>Filesystem only. Use this when a classpath resource of the same name might shadow your file.</td></tr><tr><td><code>classpath:</code></td><td><code>classpath:config/app.yml</code></td><td>Classpath only. Fails if the resource is not bundled.</td></tr></tbody></table><p>Relative filesystem paths are resolved against the current working directory, so run the jar from the repository root when using the paths in <code>examples/</code>.</p><p>See <a href="./configuration">Configuration</a> for everything the file itself can contain.</p><h2 id="web-dashboard" tabindex="-1">Web Dashboard <a class="header-anchor" href="#web-dashboard" aria-label="Permalink to &quot;Web Dashboard&quot;">​</a></h2><p><code>--web-ui</code> starts a local dashboard that shows the run as it happens - messages, tool calls, stages, output, and the triple store:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/owlsda.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/project-2/config.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --web-ui</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/owlsda.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/project-2/config.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --web-ui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --web-ui-port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9090</span></span></code></pre></div><p>The dashboard reads the benchmark snapshot directory from disk, so it needs <code>benchmark.enabled: true</code> in your configuration; without it there is nothing to show. The server stays up after the pipeline finishes so you can review the completed run - stop it with Ctrl+C. See <a href="./web-ui">Web UI</a> for what the dashboard exposes, and <a href="./benchmarking">Benchmarking</a> for the data behind it.</p><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><p>OWL-SDA itself reads exactly one environment variable:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Used by</th><th>Description</th></tr></thead><tbody><tr><td><code>OPENAI_API_KEY</code></td><td><code>client.provider: &quot;openai-compatible&quot;</code></td><td>Fallback API key when <code>client.openai-compatible.api-key</code> is unset or blank.</td></tr></tbody></table><p>Nothing else is read from the environment. When you use the default <code>copilot</code> provider, authentication is handled by the GitHub Copilot CLI itself (which has its own token variables) - see <a href="./installation">Installation</a>.</p><h2 id="exit-codes" tabindex="-1">Exit Codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit Codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>The run completed, or <code>--help</code> / <code>--version</code> was printed.</td></tr><tr><td><code>1</code></td><td>The run failed - for example the configuration file could not be read.</td></tr><tr><td><code>2</code></td><td>Usage error - a missing or unknown option.</td></tr></tbody></table>`,27)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
